  @Override
  public void queue(final T item) {
    final boolean isEmpty = pending.isEmpty();
    pending.addLast(item);
    if (isEmpty || pending.size() >= batchSize) {
      lock.lock();
      try {
        if (isEmpty) {
          startWindow.signal();
        } else {
          batchLimit.signal();
        }
      } finally {
        lock.unlock();
      }
    }
  }
